{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 3,
      "verse": 1,
      "text_ar": "في السنة الثلاثين بعد خراب المدينة، كنت أنا سالثيئيل، الذي يدعى أيضاً عزرا، في بابل، وكنت مضطجعاً على فراشي في كرب، وصعدت أفكاري إلى قلبي،",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 2,
      "text_ar": "لأني رأيت خراب صيون وثروة الساكنين في بابل.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 3,
      "text_ar": "فاضطربت روحي جداً، حتى إنه أخذني أن أكلم العلي بكلام مملوء خوفاً، وقلت:",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 4,
      "text_ar": "«أيها السيد الرب، ألم تتكلم في البدء حين صوّرت الأرض -وذلك وحدك بنفسك- وأمرت التراب،",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 5,
      "text_ar": "فأعطاك آدم، جسداً بلا نفس؟ ومع ذلك كان صنع يديك، ونفخت فيه نسمة الحياة، فأحيي قدامك.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 6,
      "text_ar": "وقدته إلى الجنة التي غرستها يمينك قبل أن تظهر الأرض.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 7,
      "text_ar": "وأعطيته وصيتك الواحدة، فتعداها، وللوقت عينت له ولنسله الموت. ومنه وُلدت أمم وأسباط وشعوب وعشائر لا تُحصى.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 8,
      "text_ar": "وسلكت كل أمة حسب إرادتها الخاصة، وصنعت أعمالاً شريرة في عينيك، وازدرت بوصاياك، فلم تمنعهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 9,
      "text_ar": "ومع ذلك، أيفضلاً بمرور الزمان، جلبت الطوفان على الساكنين في العالم وأهلكتهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 10,
      "text_ar": "وحدث أن الشيء نفسه حدث لهم، فكما جاء الموت على آدم، هكذا كان الطوفان على هؤلاء.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 11,
      "text_ar": "ومع ذلك، أبقيت واحداً منهم، نوح مع أهل بيته، وجميع الأبرار الذين تناسلوا منه.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 12,
      "text_ar": "«وحدث لما بدأ الساكنون على الأرض يتكاثرون، أنهم كثروا أيضاً أولاداً وشعوباً وأمماً كثيرة، وبدأوا ثانية يكونون أكثر شراً من آبائهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 13,
      "text_ar": "وحدث، عندما عملوا الشر قدامك، أنك اخترت واحداً منهم كان اسمه إبراهيم.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 14,
      "text_ar": "أحببته، وله وحده أظهرت نهاية الأزمنة سراً في الليل،",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 15,
      "text_ar": "وقطعت معه عهداً أبدياً، واعداً إياه بأنك لن ترفض نسله أبداً. وأعطيته إسحاق، وإسحاق أعطيته يعقوب وعيسو.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 16,
      "text_ar": "وأفرزت يعقوب لنفسك، ورذلت عيسو، فصار يعقوب جمهوراً عظيماً.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 17,
      "text_ar": "وحدث عندما أخرجت نسله من مصر، أنك صعدت بهم إلى جبل سيناء.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 18,
      "text_ar": "وطأطأت السموات أيضاً، وزلزلت الأرض، وحركت الكون بأسره، وجعلت الأعماق ترتجف، وأزعجت الدهر.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 19,
      "text_ar": "وعبر مجدك خلال أربعة أبواب: باب النار، وباب الزلزلة، وباب الريح، وباب الجليد، لكي تعطي الشريعة لنسل يعقوب، والوصية لنسل إسرائيل.",
      "review_notes_ar": []
    },
    {
      "chapter": 3,
      "verse": 20,
      "text_ar": "«ومع ذلك لم تنزع منهم قلبهم الشرير، لكي تُثمر شريعتك فيهم.",
      "review_notes_ar": []
    }
  ]
}
